using System.ComponentModel;
using System.Text.Json;
using FlMcp.Protocol;
using ModelContextProtocol.Server;

namespace FlMcp.Server;

/// <summary>MCP tools: lifecycle/ownership plus single-operation conveniences. Embedded Python (fl_execute_python)
/// is the primary editing route; these tools never define a second DAW API.</summary>
[McpServerToolType]
public sealed class FlTools(ManagedSession session)
{
    [McpServerTool(Name = "fl_instances", ReadOnly = true), Description("Discover running FL instances with FLMCP enabled, restricted to this client's configured FL executable. Does not attach, launch or edit FL. Returns processId for fl_attach.")]
    public Task<IReadOnlyList<AvailableInstance>> Instances(CancellationToken ct) => ToolErrors.Run(() => session.ListInstancesAsync(ct));

    [McpServerTool(Name = "fl_attach"), Description("Explicitly attach to the current project in a user-owned FL instance from fl_instances. Supports untitled projects. Acquires an exclusive companion lease and uses this client's workspace for snapshots/samples. Reattach after switching projects. Human edits remain concurrent; title/path identity is best effort. Never closes FL.")]
    public Task<AttachedSession> Attach(int processId, CancellationToken ct) => ToolErrors.Run(() => session.AttachAsync(processId, ct));

    [McpServerTool(Name = "fl_detach"), Description("Release the attached FL lease without closing FL, changing playback or saving. Waits for prior embedded code/native calls to finish. For disposable managed projects use fl_project_close instead.")]
    public Task<object> Detach(CancellationToken ct) => ToolErrors.Run(() => session.DetachAsync(ct));

    [McpServerTool(Name = "fl_project_start"), Description("Start a fresh isolated FL project copied from the configured template. Interactive mode requires no other FL processes. Background mode uses a private Windows desktop and permits independent MCP clients to run in parallel. Plugin must have been installed and enabled. Returns readiness plus the settled tempo and PPQ: after the bridge first answers, the tool keeps polling until tempo, PPQ and title stop changing (FL reports the template tempo until the loaded project is applied); settle.stable=false with a ProjectUnsettled warning means the bounded wait ran out. Paths are relative to workspace. Default deadline 120 seconds.")]
    public Task<SessionStatus> Start(string projectPath, CancellationToken ct, int timeoutSeconds = 120,
        [Description("Optional existing workspace FLP snapshot to resume; copied to projectPath. Omit for a fresh template project.")] string? sourceProjectPath = null,
        [Description("Launch FL on a private Windows desktop. Use this for headless operation and parallel sessions across independent MCP clients.")] bool background = false) =>
        ToolErrors.Run(() => session.LaunchAsync(projectPath, timeoutSeconds, ct, sourceProjectPath, background));

    [McpServerTool(Name = "fl_status", ReadOnly = true), Description("Read connected FL process identity, bridge readiness, project metadata, tempo and PPQ. Timing uses this project's PPQ, never a guessed default.")]
    public Task<JsonElement> Status(CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("status", new { }, ct));

    [McpServerTool(Name = "fl_channels_list", ReadOnly = true), Description("List channel rack indices (zero-based) and names.")]
    public Task<JsonElement> Channels(CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("channels", new { }, ct));

    [McpServerTool(Name = "fl_patterns_list", ReadOnly = true), Description("List patterns with one-based indices and names.")]
    public Task<JsonElement> Patterns(CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("patterns", new { }, ct));

    [McpServerTool(Name = "fl_playlist_list", ReadOnly = true), Description("List playlist track names and indices. Query before placing a clip.")]
    public Task<JsonElement> Playlist(CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("playlist", new { }, ct));

    [McpServerTool(Name = "fl_plugins_list", ReadOnly = true), Description("List installed FL plugins. effects=false lists generators; true lists mixer effects. Choose exact names returned by FL.")]
    public Task<JsonElement> Plugins(CancellationToken ct, bool effects = false) => ToolErrors.Run(() => session.CallAsync("plugins", new CatalogArgs(effects), ct));

    [McpServerTool(Name = "fl_tempo_set"), Description("Set tempo, 10..522 BPM, and return its read-back value.")]
    public Task<JsonElement> Tempo(double bpm, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("tempo", new TempoArgs(bpm), ct));

    [McpServerTool(Name = "fl_channel_add"), Description("Load an installed generator by its exact catalog name; returns the new zero-based channel index. Plugin licensing or missing content dialogs can require user action.")]
    public Task<JsonElement> Channel(string name, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("add_channel", new NameArgs(name), ct));

    [McpServerTool(Name = "fl_sample_add"), Description("Add a WAV sample already staged inside the workspace as a new sampler channel. Returns its zero-based index.")]
    public Task<JsonElement> Sample(string path, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("add_sample", new PathArgs(path), ct));

    [McpServerTool(Name = "fl_pattern_create"), Description("Create and name an empty pattern; returns its one-based index.")]
    public Task<JsonElement> Pattern(string name, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("create_pattern", new NameArgs(name), ct));

    [McpServerTool(Name = "fl_notes_add"), Description("Append 1..2048 notes to a one-based pattern. Each note uses a zero-based channel, MIDI key 0..127, PPQ startTick >=0, lengthTick >0, velocity 1..127. Query fl_status for PPQ. This appends; retries can duplicate notes.")]
    public Task<JsonElement> Notes(int pattern, Note[] notes, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("add_notes", new NotesArgs(pattern, notes), ct));

    [McpServerTool(Name = "fl_notes_read", ReadOnly = true), Description("Read pattern notes, optionally by channel (-1=all). Follow FL's continuation offset for paging.")]
    public Task<JsonElement> ReadNotes(int pattern, CancellationToken ct, int channel = -1, int offset = 0) => ToolErrors.Run(() => session.CallAsync("notes", new ReadNotesArgs(pattern, channel, offset), ct));

    [McpServerTool(Name = "fl_clip_add"), Description("Place a pattern in the playlist and select song mode for rendering. Pattern is one-based; track is one-based (1..500), using fl_playlist_list; positions and duration are PPQ ticks. Appends a clip.")]
    public Task<JsonElement> Clip(int pattern, int track, int startTick, int lengthTick, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("add_clip", new ClipArgs(pattern, track, startTick, lengthTick), ct));

    [McpServerTool(Name = "fl_mixer_set"), Description("Set a mixer track's volume as a raw native integer on FL's fader scale 0..16000: 12800 (fader 0.8, every insert's default) is 0 dB, 16000 is the fader top (+5.6 dB), 0 is silence. The law is not linear in dB; the SDK models dB = 20 * 2.889 * log10(raw / 12800), so 6400 is about -17 dB and 3200 about -35 dB (treat values below about -20 dB as +-3 dB estimates and confirm big moves by measuring). For dB values use Python instead: fl.mixer[t].set_volume(db=-6.0), fl.mixer[t].volume_db, or fruitylink.levels.mixer_volume_from_db / mixer_volume_to_db. Channel-rack volume is a different scale (0..12800, 10240 = 0 dB; fl.channels[i].set_volume(db=...)). Pan is a SIGNED mixer value -6400..6400 (0=center, negative=left, 6400=hard right); this differs from channel-rack pan (0..12800, 6400=center). Track 0=Master; active ordinary inserts are within 1..500. Use Python fl.mixer.list() for current indices; Current and dormant slots are refused.")]
    public Task<JsonElement> Mixer(int track, int volume, CancellationToken ct, int pan = 0) => ToolErrors.Run(() => session.CallAsync("mixer", new MixerArgs(track, volume, pan), ct));

    [McpServerTool(Name = "fl_markers_list", ReadOnly = true), Description("List song time markers in order with their zero-based indices and tick positions. FL extends renders and the play range to the last marker.")]
    public Task<JsonElement> Markers(CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("markers", new { }, ct));

    [McpServerTool(Name = "fl_marker_delete", Destructive = true), Description("Delete one song time marker by its zero-based index from fl_markers_list. Remove trailing markers to shorten an audition render; list again afterwards because indices shift.")]
    public Task<JsonElement> DeleteMarker(int index, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("delete_marker", new IndexArgs(index), ct));

    [McpServerTool(Name = "fl_channel_route"), Description("Route a zero-based generator channel to Master (0) or an active ordinary mixer insert (within 1..500). Use Python fl.mixer.list() for current indices.")]
    public Task<JsonElement> Route(int channel, int track, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("route", new ChannelRouteArgs(channel, track), ct));

    [McpServerTool(Name = "fl_effect_add", Destructive = true), Description("Load an installed effect by exact name into Master or an active ordinary mixer insert (0..500), slot 0..9. Use Python fl.mixer.list() for current indices. Replaces any effect already in the slot.")]
    public Task<JsonElement> Effect(int track, int slot, string name, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("add_effect", new EffectArgs(track, slot, name), ct));

    [McpServerTool(Name = "fl_parameters_list", ReadOnly = true), Description("List parameter indices and names. slot=-1 addresses a generator channel; 0..9 addresses a mixer effect slot and channelOrTrack is its mixer track.")]
    public Task<JsonElement> Parameters(int channelOrTrack, CancellationToken ct, int slot = -1, string? filter = null) => ToolErrors.Run(() => session.CallAsync("parameters", new ParamListArgs(channelOrTrack, slot, filter), ct));

    [McpServerTool(Name = "fl_parameter_set"), Description("Set a catalogued plugin parameter to normalized 0..1. slot=-1 for a generator, 0..9 for a mixer effect. Discover indices before use.")]
    public Task<JsonElement> Parameter(int channelOrTrack, int slot, int parameter, double value, CancellationToken ct) => ToolErrors.Run(() => session.CallAsync("set_parameter", new ParamArgs(channelOrTrack, slot, parameter, value), ct));

    [McpServerTool(Name = "fl_project_save"), Description("Save a verified FLP snapshot inside the workspace without changing project identity. Attached sessions preserve playback and song mode; disposable sessions stop playback and select song mode. Existing files are refused; use a fresh path.")]
    public Task<object> Save(string projectPath, CancellationToken ct) => ToolErrors.Run(() => session.SaveAsync(projectPath, ct));

    [McpServerTool(Name = "fl_project_close", Destructive = true), Description("Save to a fresh workspace FLP path, verify the snapshot, then terminate only the disposable managed editor. Refuses user-owned attached sessions. Use MCP request cancellation to interrupt an active launch or render first.")]
    public Task<object> Close(string projectPath, CancellationToken ct) => ToolErrors.Run(() => session.CloseAsync(projectPath, ct));

    [McpServerTool(Name = "fl_project_render", Destructive = true), Description("Save a verified snapshot, end the disposable editing session, and render it to a new WAV using FL's documented CLI. Output must be inside workspace and not exist. Uses FL's saved render settings; requires a working licensed GUI installation. Waits for renderer exit and validates WAV; default deadline 600s (max3600) per attempt. A renderer that exits nonzero, leaves an invalid WAV, or leaves a WAV shorter than the project's span (last clip end or last marker at the current tempo) is treated as a partial render: the partial file is moved to <name>.failed-attempt1.wav and the same snapshot is rendered once more; a second failure returns both attempts' evidence (exit codes, lengths, moved files, host log tail). Deadline expiry is not retried. A successful result includes audio path and snapshot path for other MCPs such as Blender. This closes the managed editing session. Refuses user-owned attached sessions. Optional startBar/endBar (one-based, inclusive) render only that section: the untrimmed project is saved as <name>-full.flp, then the live project is trimmed to the span (clips outside deleted, survivors shifted to bar 1, markers removed) before the render snapshot; a clip that begins before startBar is refused unless cutClips=true. A section render ends exactly at endBar (the markers that would extend it are removed); pass tailBeats to keep reverb and release tails.")]
    public Task<RenderResult> Render(string outputPath, CancellationToken ct, int timeoutSeconds = 600,
        [Description("Optional first bar of a section render (one-based). Requires endBar.")] int? startBar = null,
        [Description("Optional last bar of a section render, inclusive (bars 49..64 render sixteen bars). Requires startBar.")] int? endBar = null,
        [Description("Allow clips that begin before startBar to be cut there. A cut pattern clip restarts from its first beat; audio and automation clips keep their offset. Default false refuses such clips.")] bool cutClips = false,
        [Description("Beats of tail to keep after endBar in a section render (an End marker is placed that far past the span so tails ring out). Default 0 renders exactly the span. Requires startBar/endBar.")] double tailBeats = 0) =>
        ToolErrors.Run(() => session.RenderAsync(outputPath, timeoutSeconds, ct, RenderRange.From(startBar, endBar, cutClips, tailBeats)));

    [McpServerTool(Name = "fl_execute_python", Destructive = true), Description("Execute trusted Python embedded inside FL Studio with the reusable fruitylink SDK; this is the primary way to inspect and edit projects, running many operations per request. Globals include fl (Studio) with channels/patterns/clips/mixer/automation/transport/plugins helpers, fl.ops, fl.analysis (offline WAV analysis plus describe_audio/compare_audio/describe_samples: agent-readable text descriptions), fl.samples (describe a sampler channel's file), fl.audio (live per-insert capture through FL's disk recording and the live-vs-render section policy; it never renders) and dB volume helpers (fl.mixer[t].set_volume(db=), fl.channels[i].set_volume(db=), fruitylink.levels); assign a JSON-compatible result with string dict keys. Use fl_python_docs and fl_python_api first. A script exception returns ok:false with error, traceback, the stdout/stderr captured before it and any result assigned before it (resultPartial). Responses over FL_MCP_PYTHON_RESPONSE_LIMIT (default 64 KiB) are saved to <workspace>/results/*.json and returned as {oversized,totalBytes,path,head,tail}; read the file for the rest. The 1..300 second deadline requests cooperative cancellation. Blocking native calls must finish before execution returns or FL can close. Completed edits remain. Python shares FL's process and account permissions. Requires fl_project_start or fl_attach; use MCP project tools for lifecycle and rendering.")]
    public Task<JsonElement> ExecutePython(string code, CancellationToken ct, int timeoutSeconds = 60) =>
        ToolErrors.Run(() => session.ExecutePythonAsync(code, timeoutSeconds, ct));

    [McpServerTool(Name = "fl_python_api", ReadOnly = true), Description("Discover the current SDK scripting operations, typed arguments, descriptions and defaults. Optional filter matches operation name or description. Generated from the shared public SDK contract; each operation carries pythonSignature and each argument/result field carries pythonName (snake_case) for use in fl_execute_python. Requires fl_project_start or fl_attach.")]
    public Task<JsonElement> PythonApi(CancellationToken ct, string? filter = null) => ToolErrors.Run(() => session.PythonApiAsync(filter, ct));

    [McpServerTool(Name = "fl_python_docs", ReadOnly = true), Description("Read Python execution conventions, helper classes (including fl.analysis describe/compare, fl.audio live capture and the dB volume helpers), naming rules, result rules and project lifecycle guidance. Embedded Python (fl_execute_python) is the primary way to work; read this first. Available before starting FL.")]
    public string PythonDocs() => PythonDocumentation.For(session.InstalledPythonPackage);

    [McpServerTool(Name = "fl_audio_describe", ReadOnly = true), Description("Describe a WAV (a render, a live capture or a sample) as compact text an agent can read instead of listening: level (peak, RMS, crest, integrated LUFS), an ASCII envelope sketch, onsets as bar:beat at the project tempo, attack/decay/tail times, head and tail silence, spectral segments (centroid, tilt, flatness, seven band levels sub..air), tonality with root note, stereo width, loop hints and character tags (sub-heavy, harsh 2-4 kHz, bright, dark, wide, clicky attack, one-shot, loopable...). Pass exactly one of path (an existing .wav; relative paths resolve inside the workspace, so a fl_project_render output can be named as returned) or channel (the zero-based index of a sampler channel this session loaded through fl_sample_add or fl.channels.add_sample; FL exposes no sampler-file query, so other channels need path). detail brief/normal/full sets envelope slices (16/32/64), spectral segments on long audio (0/4/8) and onsets listed (6/8/24). compareWith names a baseline WAV: the result adds comparison.text with deltas of the subject minus the baseline (level, decay, centroid, tilt, bands, width, tags added/removed, verdicts) for one-call A/B checks. Runs fruitylink.analysis.describe_audio inside the live session's Python with bpm/ppq taken from the project (about 0.1 s for a one-shot, a few seconds for a 4-minute master with numpy installed, longer without); never edits FL and reads no live audio. Returns source, kind, bpm, ppq, detail, text, tags, data (the same numbers as JSON), comparison and elapsedSeconds. Requires fl_project_start or fl_attach.")]
    public Task<JsonElement> AudioDescribe(CancellationToken ct,
        [Description("Existing .wav to describe. Absolute, or relative to the workspace. Exactly one of path/channel.")] string? path = null,
        [Description("Zero-based channel-rack index of a sampler channel whose file this session loaded. Exactly one of path/channel.")] int? channel = null,
        [Description("brief, normal (default) or full.")] string detail = "normal",
        [Description("Optional baseline .wav; the result then also carries compare_audio(baseline, subject) as comparison.")] string? compareWith = null) =>
        ToolErrors.Run(() => session.DescribeAudioAsync(path, channel, detail, compareWith, ct));

    [McpServerTool(Name = "fl_audio_capture"), Description("Record what mixer inserts actually output (post-FX, after their whole effect chain) for bars startBar..endBar (one-based, endBar INCLUSIVE: 33..36 is four bars) by playing that span once while FL's own disk recording writes one WAV per armed insert, then measure each WAV offline. Nothing is rendered and the session stays open, but the pass DOES edit the project: FL adds one sample channel and one playlist clip per recording even with Auto-create audio clip off; the SDK deletes the clips and retires the channels (renamed \"(unused) ...\", muted, routed to Master) because FL has no channel delete, so retired channels remain in the channel rack (deleted_clips / retired_channels report them; save a snapshot first if that matters). FL prerequisites (live-verified on FL 26.1.3): the record button's Recording filter (right-click the record button) must include Audio, and mixer menu > Disk recording > Auto-create audio clip should be off; with the filter wrong FL writes no file and the CaptureError says so. inserts is \"master\" (default) or an array of mixer track indices (0 = Master; active inserts from fl.mixer.list()). tailBeats keeps that many beats after endBar so reverb and release tails are captured. name copies the recordings as <name>-<track>.wav beside FL's originals in its recorded-audio folder (Documents\\Image-Line\\FL Studio\\Audio\\Recorded) and, unless keepOriginals=true, deletes FL's auto-named originals once each copy verifies (removed_originals); without name FL's own files are the result. armRefresh (default true) applies the FL quirk workaround that arms and disarms one extra non-requested insert so FL registers the recording set (a single armed insert otherwise writes no file); the applied or skipped workaround is noted in warnings. The transport must be stopped: song mode is selected, any loop selection is cleared for the pass and restored, the playhead is seeked to startBar, record+play run until the playhead passes the end, and the inserts armed here are disarmed afterwards. Real time: a 16-bar section at 100 BPM plays for 38 s plus about 10 s of overhead; the tool's deadline is the span plus 90 s (120..900). Returns the SDK's CaptureResult (method is the SDK's name fl_disk_recording), plan (ticks, seconds, bpm, ppq), files (one per insert: track, name, path, sample_rate, channel_count, frames, seconds), captured_start_tick/captured_end_tick, complete, stop_tick, measurements per track (peak_dbfs, rms_dbfs, integrated_lufs, short_term_lufs, full_db, bands, per-bar rows with rms/peak/crest/centroid/correlation/bands/lufs, covered_bars, partial; a measurement that failed is {error: ...}), descriptions (brief fl_audio_describe text per WAV), recorded_folder, warnings (arm-refresh applied/skipped, early FL stop, deadline, disarm failure, cleanup problems), deleted_clips, retired_channels, removed_originals, python_seconds, elapsedSeconds and timeoutSeconds. Errors return the SDK's CaptureError text verbatim: the record-arm routines are refused on FL builds where the native arm symbols are unresolved, the recorded-audio folder may be missing, other armed inserts also record. Requires fl_project_start or fl_attach.")]
    public Task<JsonElement> AudioCapture(int startBar, int endBar, CancellationToken ct,
        [Description("\"master\" (default when omitted) or an array of mixer track indices 0..500; 0 is Master.")] JsonElement? inserts = null,
        [Description("Beats to keep recording after endBar for tails. Default 0.")] double tailBeats = 0,
        [Description("Optional 1..80-character name; recordings are copied as <name>-<track>.wav beside FL's originals, which are then deleted unless keepOriginals.")] string? name = null,
        [Description("Apply the arm-refresh workaround (arm and disarm one extra insert so FL registers the recording set). Default true; false only to reproduce the quirk.")] bool armRefresh = true,
        [Description("With name: keep FL's auto-named originals beside the copies. Default false. Refused without name.")] bool keepOriginals = false) =>
        ToolErrors.Run(() => session.CaptureAudioAsync(inserts, startBar, endBar, tailBeats, name, armRefresh, keepOriginals, ct));

    [McpServerTool(Name = "fl_section_measure", Destructive = true), Description("Measure bars startBar..endBar (one-based, endBar INCLUSIVE; peak/RMS dBFS, integrated and short-term LUFS, band levels, per-bar rows and a brief description) by the cheaper of two routes: a live capture (fl_audio_capture semantics, same FL prerequisites: the record button's Recording filter must include Audio and mixer menu > Disk recording > Auto-create audio clip should be off; the pass leaves one retired \"(unused)\" sample channel per recording because FL has no channel delete) for short sections or an offline section render for long ones, chosen by the SDK's fruitylink.capture.CapturePolicy (live costs the span in real time plus about 8 s; a render about 45 s plus an eighth of the span; live is capped at 120 s of music, so the break-even is about 42 s). prefer=auto lets the policy decide; live or render forces a route. Omit inserts to measure the master; an explicit inserts array measures those inserts and forces the live route (a render only yields the master). tailBeats keeps tails after endBar. Returns one record either way: method live|render plus sdkMethod with the SDK's own name (fl_disk_recording|offline_render, what fl.audio.measure_section reports), decision (both cost estimates and the reason), inserts, bpm, ppq, files and measurements and descriptions per track, capture (live: the fl_audio_capture record without its measurements: plan, captured ticks, complete, recorded_folder, deleted_clips, retired_channels, removed_originals, warnings) or render (the fl_project_render result: path, seconds, expectedSeconds, project, fullProject, range, attempts), sessionClosed, sessionReopenedFrom, resumedProject, resumedStatus, timing (totalSeconds plus captureSeconds or decide/render/reopen/measureSeconds and pythonSeconds, for tuning the policy defaults) and warnings. THE RENDER ROUTE CLOSES THE MANAGED EDITING SESSION exactly as fl_project_render does: it saves the untrimmed project as <name>-full.flp, trims the live project to the span (cutClips=true, tailBeats), snapshots and renders measure/<project>-bars<start>-<end>-<stamp>.wav; then, because measuring needs the embedded SDK, it reopens the -full.flp as a new managed project (measure/...-resumed.flp, returned as resumedProject with its settled status) and measures the WAV there, so later calls work in that reopened copy (sessionClosed=true and sessionReopenedFrom say so). If the reopen or the measurement fails the render result is still returned with measurements=null and a MeasurementUnavailable/MeasurementFailed warning naming the snapshot to resume with fl_project_start(sourceProjectPath). Attached (user-owned) sessions are never rendered or closed: the render route is refused for them, pass prefer=live. timeoutSeconds is the render deadline per attempt (default 600, max 3600); the reopen uses at most 300 s. Requires fl_project_start or fl_attach.")]
    public Task<JsonElement> SectionMeasure(int startBar, int endBar, CancellationToken ct,
        [Description("Omit for the master; an array of mixer track indices 0..500 measures those inserts and forces a live capture.")] JsonElement? inserts = null,
        [Description("auto (default: the policy chooses), live or render.")] string prefer = "auto",
        [Description("Beats of tail to keep after endBar (recorded live, or an End marker past the span in a render). Default 0.")] double tailBeats = 0,
        [Description("Render deadline per attempt in seconds, 1..3600 (default 600); the reopen after a render uses at most 300.")] int timeoutSeconds = 600) =>
        ToolErrors.Run(() => session.MeasureSectionAsync(startBar, endBar, inserts, prefer, tailBeats, timeoutSeconds, ct));
}
